schemaSql:
-- Dynamic USD Rate & System Settings
create table if not exists public.taregba_settings (
  id bigint primary key generated always as identity,
  setting_key text unique not null,
  setting_value text not null,
  updated_at timestamptz default now()
);

-- Bank Account Info for Customer Bank Transfers
create table if not exists public.taregba_bank_settings (
  id bigint primary key generated always as identity,
  bank_name text not null,
  account_number text not null,
  account_holder text not null,
  customer_note text,
  updated_at timestamptz default now()
);

-- Delivery Areas & Fees
create table if not exists public.taregba_delivery_areas (
  id bigint primary key generated always as identity,
  name text unique not null,
  delivery_fee_sdg numeric(12,2) not null default 0,
  is_active boolean not null default true,
  created_at timestamptz default now()
);

-- Products Catalog
create table if not exists public.taregba_products (
  id bigint primary key generated always as identity,
  name text not null,
  category text not null,
  description text,
  price_usd numeric(10,2) not null check (price_usd >= 0),
  stock_quantity integer not null default 0 check (stock_quantity >= 0),
  low_stock_threshold integer not null default 5 check (low_stock_threshold >= 0),
  image_url text,
  is_visible boolean not null default true,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Orders Main Table
create table if not exists public.taregba_orders (
  id bigint primary key generated always as identity,
  order_number text unique not null,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  full_name text not null,
  phone text not null,
  delivery_area_id bigint references public.taregba_delivery_areas(id) on delete set null,
  delivery_area_name text not null,
  delivery_address text,
  delivery_type text not null default 'delivery' check (delivery_type in ('delivery', 'pickup')),
  delivery_fee_sdg numeric(12,2) not null default 0,
  subtotal_sdg numeric(12,2) not null default 0,
  total_sdg numeric(12,2) not null default 0,
  status text not null default 'new' check (status in ('new', 'preparing', 'on_the_way', 'completed', 'cancelled')),
  payment_method text not null check (payment_method in ('cash', 'transfer')),
  payment_status text not null default 'pending' check (payment_status in ('pending', 'confirmed', 'rejected')),
  receipt_url text,
  reject_reason text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Order Items Detail Table
create table if not exists public.taregba_order_items (
  id bigint primary key generated always as identity,
  order_id bigint not null references public.taregba_orders(id) on delete cascade,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  product_id bigint references public.taregba_products(id) on delete set null,
  product_name text not null,
  unit_price_usd numeric(10,2) not null default 0,
  unit_price_sdg numeric(12,2) not null default 0,
  quantity integer not null check (quantity > 0),
  total_price_sdg numeric(12,2) not null default 0,
  created_at timestamptz default now()
);

-- Purchases / Invoices (Admin Expense Records)
create table if not exists public.taregba_purchases (
  id bigint primary key generated always as identity,
  supplier_name text not null,
  purchase_date date not null default current_date,
  total_amount_sdg numeric(12,2) not null check (total_amount_sdg >= 0),
  payment_status text not null check (payment_status in ('paid', 'credit')),
  invoice_image_url text,
  created_by uuid not null default auth.uid() references auth.users(id) on delete cascade,
  created_at timestamptz default now()
);

-- Broadcast Offers & Promotional Push Notifications Log
create table if not exists public.taregba_promotions (
  id bigint primary key generated always as identity,
  title text not null,
  message text not null,
  sent_at timestamptz default now(),
  created_by uuid not null default auth.uid() references auth.users(id) on delete cascade
);

-- Enable Row Level Security on all created tables
alter table public.taregba_settings enable row level security;
alter table public.taregba_bank_settings enable row level security;
alter table public.taregba_delivery_areas enable row level security;
alter table public.taregba_products enable row level security;
alter table public.taregba_orders enable row level security;
alter table public.taregba_order_items enable row level security;
alter table public.taregba_purchases enable row level security;
alter table public.taregba_promotions enable row level security;

-- Policies for taregba_settings
drop policy if exists "Settings visible to authenticated users" on public.taregba_settings;
create policy "Settings visible to authenticated users"
  on public.taregba_settings for select
  to authenticated
  using (true);

drop policy if exists "Settings manageable by admin" on public.taregba_settings;
create policy "Settings manageable by admin"
  on public.taregba_settings for all
  to authenticated
  using (public.taregba_is_admin())
  with check (public.taregba_is_admin());

