-- Policies for taregba_products
drop policy if exists "Products visible to authenticated users" on public.taregba_products;
create policy "Products visible to authenticated users"
  on public.taregba_products for select
  to authenticated
  using (true);

drop policy if exists "Products manageable by admin" on public.taregba_products;
create policy "Products manageable by admin"
  on public.taregba_products for all
