-- Policies for taregba_orders
drop policy if exists "Customers can view their own orders or admin views all" on public.taregba_orders;
create policy "Customers can view their own orders or admin views all"
  on public.taregba_orders for select
  to authenticated
  using (customer_id = auth.uid() or public.taregba_is_admin());

drop policy if exists "Customers can insert their own orders" on public.taregba_orders;
create policy "Customers can insert their own orders"
  on public.taregba_orders for insert
  to authenticated
  with check (customer_id = auth.uid() or public.taregba_is_admin());

drop policy if exists "Customers can update receipts on pending orders or admin full update" on public.taregba_orders;
create policy "Customers can update receipts on pending orders or admin full update"
  on public.taregba_orders for update
  to authenticated
  using (customer_id = auth.uid() or public.taregba_is_admin())
  with check (customer_id = auth.uid() or public.taregba_is_admin());

drop policy if exists "Orders deletable by admin only" on public.taregba_orders;
create policy "Orders deletable by admin only"
  on public.taregba_orders for delete
  to authenticated
  using (public.taregba_is_admin());

-- Policies for taregba_order_items
drop policy if exists "Order items visible to order owner or admin" on public.taregba_order_items;
create policy "Order items visible to order owner or admin"
  on public.taregba_order_items for select
  to authenticated
  using (customer_id = auth.uid() or public.taregba_is_admin());

drop policy if exists "Order items insertable by order owner or admin" on public.taregba_order_items;
create policy "Order items insertable by order owner or admin"
  on public.taregba_order_items for insert
  to authenticated
  with check (customer_id = auth.uid() or public.taregba_is_admin());

drop policy if exists "Order items manageable by admin" on public.taregba_order_items;
create policy "Order items manageable by admin"
  on public.taregba_order_items for all
  to authenticated
  using (public.taregba_is_admin())
  with check (public.taregba_is_admin());

-- Policies for taregba_purchases
drop policy if exists "Purchases manageable by admin only" on public.taregba_purchases;
create policy "Purchases manageable by admin only"
  on public.taregba_purchases for all
  to authenticated
  using (public.taregba_is_admin())
  with check (public.taregba_is_admin());

-- Policies for taregba_promotions
drop policy if exists "Promotions viewable by authenticated users" on public.taregba_promotions;
create policy "Promotions viewable by authenticated users"
  on public.taregba_promotions for select
  to authenticated
  using (true);

drop policy if exists "Promotions insertable by admin" on public.taregba_promotions;
create policy "Promotions insertable by admin"
  on public.taregba_promotions for insert
  to authenticated
  with check (public.taregba_is_admin());

